export type SeedStatus = 'draft' | 'active' | 'paused' | 'retired' | 'prohibited';
export type EvidenceTier = 'A' | 'B' | 'C' | 'D' | 'X';
export type SourceType = 'guideline' | 'meta_analysis' | 'systematic_review' | 'rct' | 'professional_manual' | 'coaching_reference';

export interface SeedSource {
  sourceType: SourceType;
  citationText: string;
  sourceUrl: string;
  publicationYear: number;
  supports: string;
  limitations: string;
  licenseNotes: string;
  reviewed: boolean;
  reviewedBy: string;
}

export interface CatalogSeedCard {
  code: string;
  version: number;
  status: SeedStatus;
  titleAr: string;
  shortDescriptionAr: string;
  framework: string;
  evidenceTier: EvidenceTier;
  contentOrigin: string;
  licensingStatus: 'cleared_original' | 'licensed' | 'review_required' | 'restricted';
  targetNeeds: string[];
  targetPatterns: string[];
  eligibleStates: string[];
  journeyDomains: string[];
  exclusions: string[];
  contraindicationNotesAr: string;
  durationMin: number;
  stepsAr: string[];
  actionTemplateAr: string;
  measurementSpec: Record<string, unknown>;
  followUpSpec: Record<string, unknown>;
  fallbackCode: string | null;
  requiresUserConfirmation: boolean;
  scientificReviewStatus: 'pending' | 'reviewed' | 'rejected';
  clinicalBoundaryReviewStatus: 'pending' | 'reviewed' | 'rejected';
  requiresHumanSupport: boolean;
  sources: SeedSource[];
}

