const basicMeasure = (primary = 'intensity') => ({
  before: [`${primary}_before`],
  after: [`${primary}_after`],
  outcome: ['action_outcome','user_helpfulness'],
});
const follow = (timing: 'later_today' | 'tomorrow' | 'after_event' = 'later_today', prompt = 'شو صار بعد ما جربتي الخطوة؟') => ({ timing, prompt });

function card(input: Omit<CatalogSeedCard, 'version' | 'licensingStatus' | 'scientificReviewStatus' | 'clinicalBoundaryReviewStatus' | 'requiresHumanSupport'> & Partial<Pick<CatalogSeedCard, 'version' | 'licensingStatus' | 'scientificReviewStatus' | 'clinicalBoundaryReviewStatus' | 'requiresHumanSupport'>>): CatalogSeedCard {
  return {
    version: 1,
    licensingStatus: 'cleared_original',
    scientificReviewStatus: input.status === 'active' ? 'reviewed' : 'reviewed',
    clinicalBoundaryReviewStatus: input.status === 'active' ? 'reviewed' : 'pending',
    requiresHumanSupport: false,
    ...input,
  };
}

